insert into atlas_opportunities_stage (
  id, external_id, company_id, name, normalized_name, opportunity_type, pipeline_stage, probability,
  fit_score, priority, expected_close_date, next_action, description, notes_summary, tags
)
select
  payload.id::uuid, payload."externalId", payload."companyId"::uuid, payload.name, payload."normalizedName",
  payload."opportunityType", payload."pipelineStage", payload.probability, payload."fitScore",
  payload.priority, payload."expectedCloseDate"::date, payload."nextAction", payload.description,
  payload."notesSummary", array(select jsonb_array_elements_text(payload.tags))
